@import url('https://fonts.googleapis.com/css2?family=Albert+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Netflix DNA — cinematic black, signal red, UI recedes behind imagery */
.theme-netflix-dna {
  --bg: oklch(0.000 0 0);
  --surface: oklch(0.191 0 0);
  --surface-2: oklch(0.256 0 0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.735 0 0);
  --accent: oklch(0.581 0.235 28.0);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.496 0.199 28.6);
  --line: oklch(1 0 0 / 15%);
  --success: oklch(0.768 0.190 148.1);
  --warning: oklch(0.789 0.160 87.2);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.25rem;
  --radius-sm: 0.125rem;
  --radius-lg: 0.375rem;
  --radius-pill: 0.375rem;
  --shadow-1: 0 4px 16px oklch(0 0 0 / 60%);
  --shadow-2: 0 12px 40px oklch(0 0 0 / 70%);
  --shadow-3: 0 32px 80px oklch(0 0 0 / 80%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Albert Sans", sans-serif;
  --font-body: "Albert Sans", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: -0.02em;
  --label-transform: none;
  --label-tracking: 0.08em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-netflix-dna h1,
.theme-netflix-dna h2,
.theme-netflix-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-netflix-dna { background-image: radial-gradient(ellipse at 50% -20%, oklch(0.3 0.1 25 / 45%), transparent 55%); }
.theme-netflix-dna h1 { font-weight: 900; text-transform: uppercase; letter-spacing: -0.02em; }
.theme-netflix-dna button { font-weight: 700; }

/* depth */
.theme-netflix-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-netflix-dna a { color: var(--fg); text-decoration: none; }
.theme-netflix-dna a:hover { color: var(--fg-muted); } /* nav links dim, never underline */
.theme-netflix-dna :is(a, button, input, select, textarea, [tabindex]):focus-visible { outline: 2px solid oklch(1 0 0); outline-offset: 2px; } /* TV-remote focus ring */
.theme-netflix-dna thead th { font-size: 0.75rem; font-weight: 600; color: var(--fg-muted); border-bottom: 1px solid var(--line); text-align: left; }
.theme-netflix-dna tbody td { border-bottom: 1px solid oklch(1 0 0 / 8%); }
.theme-netflix-dna tbody tr:hover td { background: oklch(1 0 0 / 6%); }
.theme-netflix-dna input, .theme-netflix-dna select, .theme-netflix-dna textarea { background: oklch(1 0 0 / 12%); border: 1px solid oklch(1 0 0 / 25%); border-radius: var(--radius); color: var(--fg); }
.theme-netflix-dna input::placeholder, .theme-netflix-dna textarea::placeholder { color: var(--fg-muted); }
.theme-netflix-dna input:focus-visible, .theme-netflix-dna select:focus-visible, .theme-netflix-dna textarea:focus-visible { outline-offset: 0; border-color: transparent; background: oklch(1 0 0 / 16%); }
.theme-netflix-dna button { transition: filter 120ms ease, background-color 120ms ease; }
.theme-netflix-dna button:active { filter: brightness(0.78); } /* red button presses to deep crimson */
.theme-netflix-dna kbd { background: var(--surface-2); border: 1px solid var(--line); border-bottom-width: 2px; border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); font-size: 0.8em; }
.theme-netflix-dna ::-webkit-scrollbar { width: 12px; height: 12px; }
.theme-netflix-dna ::-webkit-scrollbar-track { background: var(--bg); }
.theme-netflix-dna ::-webkit-scrollbar-thumb { background: oklch(0.35 0 0); border-radius: 6px; border: 2px solid var(--bg); }
.theme-netflix-dna ::-webkit-scrollbar-thumb:hover { background: oklch(0.48 0 0); }
.theme-netflix-dna .label-caps { color: var(--accent); font-weight: 700; letter-spacing: 0.12em; text-transform: uppercase; } /* "N SERIES" red eyebrow */
.theme-netflix-dna .themed-border { border-color: var(--accent); }
.theme-netflix-dna hr { border: none; border-top: 1px solid oklch(1 0 0 / 10%); }

/* alt mode: one-sheet poster — warm paper, red halo kept */
.theme-netflix-dna.alt-mode {
  --bg: oklch(0.975 0.004 60);
  --surface: oklch(0.945 0.006 50);
  --surface-2: oklch(0.905 0.008 45);
  --fg: oklch(0.15 0.005 30);
  --fg-muted: oklch(0.45 0.015 30);
  --line: oklch(0.86 0.01 40);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
  background-image: radial-gradient(ellipse at 50% -20%, oklch(0.88 0.05 27 / 55%), transparent 55%);
}
.theme-netflix-dna.alt-mode :is(a, button, input, select, textarea, [tabindex]):focus-visible { outline-color: oklch(0.15 0.005 30); }
.theme-netflix-dna.alt-mode tbody td { border-bottom-color: oklch(0 0 0 / 8%); }
.theme-netflix-dna.alt-mode tbody tr:hover td { background: oklch(0 0 0 / 5%); }
.theme-netflix-dna.alt-mode input, .theme-netflix-dna.alt-mode select, .theme-netflix-dna.alt-mode textarea { background: oklch(0 0 0 / 5%); border-color: oklch(0 0 0 / 20%); }
.theme-netflix-dna.alt-mode ::-webkit-scrollbar-thumb { background: oklch(0.72 0.01 40); border-color: var(--bg); }
.theme-netflix-dna.alt-mode hr { border-top-color: oklch(0 0 0 / 10%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
